### 示例 4：双缓冲优化版本

```c
/*********************************************
 * 使用双缓冲技术避免第二次屏障同步
 * 
 * 原理：
 *   - 使用两个共享内存缓冲区
 *   - 一个用于读取，一个用于写入
 *   - 每次迭代交换读写角色
 *   - 避免写后读竞争，因为读写操作在不同的缓冲区
 *********************************************/
__global__ void Kogge_Stone_scan_double_buffer(float *X, float *Y, unsigned int N) {
    // 声明两个共享内存缓冲区
    __shared__ float XY0[SECTION_SIZE];
    __shared__ float XY1[SECTION_SIZE];

    unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;

    // 初始加载到第一个缓冲区
    if(i < N) {
        XY0[threadIdx.x] = X[i];
    } else {
        XY0[threadIdx.x] = 0.0f;
    }

    // 指针用于交替访问两个缓冲区
    float *in = XY0;   // 输入缓冲区
    float *out = XY1;  // 输出缓冲区

    for(unsigned int stride = 1; stride < blockDim.x; stride *= 2) {
        // 只需要一次屏障同步
        __syncthreads();

        if(threadIdx.x >= stride) {
            // 从输入缓冲区读取，写入输出缓冲区
            // 不会产生竞争条件，因为读写操作在不同的缓冲区
            out[threadIdx.x] = in[threadIdx.x] + in[threadIdx.x - stride];
        } else {
            // 对于不活跃的线程，直接复制数据
            out[threadIdx.x] = in[threadIdx.x];
        }

        // 交换缓冲区指针
        // 下一次迭代时，当前的输出缓冲区变为输入缓冲区
        float *temp = in;
        in = out;
        out = temp;
    }

    // 最终结果在 in 缓冲区中（因为最后一次迭代交换了指针）
    if(i < N) {
        Y[i] = in[threadIdx.x];
    }
}

/* 双缓冲的优势：
 * 1. 减少同步次数：从 2×log₂(N) 降到 log₂(N)
 * 2. 避免写后读竞争：读写操作在不同缓冲区
 * 3. 提高性能：同步是昂贵的操作
 * 
 * 双缓冲的代价：
 * 1. 增加共享内存使用：从 1 个缓冲区增加到 2 个
 * 2. 需要额外的指针交换逻辑
 * 3. 不活跃线程需要复制数据
 * 
 * 适用场景：
 * - 共享内存充足
 * - 同步开销成为瓶颈
 * - 追求极致性能
 */
```

