// 查找所有子串出现位置
int find_all_occurrences(char *text, int text_len, 
                         char *pattern, int pattern_len,
                         int *positions) {
    int *matches = new int[text_len];

    // 标记匹配起始位置
    for (int i = 0; i <= text_len - pattern_len; i++) {
        matches[i] = (strncmp(&text[i], pattern, pattern_len) == 0) ? 1 : 0;
    }

    // 排除扫描
    int pos = 0;
    int *temp = new int[text_len];
    for (int i = 0; i < text_len; i++) {
        temp[i] = pos;
        pos += matches[i];
    }

    // 收集位置
    int count = 0;
    for (int i = 0; i < text_len; i++) {
        if (matches[i]) {
            positions[temp[i]] = i;
            count++;
        }
    }

    delete[] matches;
    delete[] temp;
    return count;
}
```

