// 并行 GROUP BY 计数
void parallel_group_by(int *keys, int *values, int N,
                       int *group_keys, int *group_counts) {
    // 假设 keys 已排序
    // 标记组边界
    int *boundaries = new int[N];
    boundaries[0] = 1;
    for (int i = 1; i < N; i++) {
        boundaries[i] = (keys[i] != keys[i-1]) ? 1 : 0;
    }

    // 排除扫描得到组索引
    int group_idx = 0;
    int *group_indices = new int[N];
    for (int i = 0; i < N; i++) {
        group_indices[i] = group_idx;
        group_idx += boundaries[i];
    }

    // 收集组信息
    int num_groups = 0;
    for (int i = 0; i < N; i++) {
        if (boundaries[i]) {
            group_keys[num_groups] = keys[i];
            group_counts[num_groups] = 0;
            num_groups++;
        }
        group_counts[group_indices[i]]++;
    }

    delete[] boundaries;
    delete[] group_indices;
}
```

