// 计算累积分布函数（CDF）
void compute_cdf(float *data, int N, float *cdf) {
    // 假设 data 已排序
    // 每个值的 CDF = (小于该值的数量) / N

    float *counts = new float[N];

    // 统计每个值的出现次数（简化版，假设值唯一）
    for (int i = 0; i < N; i++) {
        counts[i] = 1.0f / N;
    }

    // 包含扫描得到 CDF
    cdf[0] = counts[0];
    for (int i = 1; i < N; i++) {
        cdf[i] = cdf[i-1] + counts[i];
    }

    delete[] counts;
}
```

