// 计算积分图像（Integral Image）
void compute_integral_image(float *image, int width, int height,
                            float *integral) {
    // 行扫描
    for (int y = 0; y < height; y++) {
        integral[y * width + 0] = image[y * width + 0];
        for (int x = 1; x < width; x++) {
            integral[y * width + x] = integral[y * width + x-1] 
                                      + image[y * width + x];
        }
    }

    // 列扫描
    for (int x = 0; x < width; x++) {
        for (int y = 1; y < height; y++) {
            integral[y * width + x] += integral[(y-1) * width + x];
        }
    }
}

// 使用积分图像快速计算矩形区域和
float rectangle_sum(float *integral, int width,
                   int x1, int y1, int x2, int y2) {
    return integral[y2 * width + x2]
         - integral[y1 * width + x2]
         - integral[y2 * width + x1]
         + integral[y1 * width + x1];
}
