// Softmax 函数计算（需要指数和的前缀和）
void softmax(float *logits, int N, float *probs) {
    // 计算指数
    float *exps = new float[N];
    float max_logit = logits[0];
    for (int i = 1; i < N; i++) {
        if (logits[i] > max_logit) max_logit = logits[i];
    }

    for (int i = 0; i < N; i++) {
        exps[i] = expf(logits[i] - max_logit);
    }

    // 计算总和（包含扫描的最后一个元素）
    float sum = 0.0f;
    for (int i = 0; i < N; i++) {
        sum += exps[i];
    }

    // 归一化
    for (int i = 0; i < N; i++) {
        probs[i] = exps[i] / sum;
    }

    delete[] exps;
}
```

